update ctrl.watermark 
set watermark_value = sysutcdatetime()
where table_id=@{pipeline().parameters.table_id}

query.value:
@concat(
    'SELECT * FROM public.',
    activity('Read Table Details').output.firstRow.source_table_name,
    if(
        equals(
            activity('Read Table Details').output.firstRow.load_type,
            'FULL'
        ),
        '',
        concat(
            ' WHERE ',
            activity('Read Table Details').output.firstRow.watermark_column,
            ' > ',
            '''',
            variables('watermark_value'),
            ''''
        )
    )
)

p_relative_url.value:
@concat(
    activity('Read Table Details').output.firstRow.source_relative_url,
    if(
        equals(
            activity('Read Table Details').output.firstRow.url_parameter_strategy,
            'SINCE_PER_PAGE'
        ),
        concat(
            '?since=',
            formatDateTime(variables('watermark_value'), 'yyyy-MM-ddTHH:mm:ssZ'),
            '&',
            activity('Read Table Details').output.firstRow.source_api_params
        ),
        if(
            equals(
                activity('Read Table Details').output.firstRow.url_parameter_strategy,
                'SORT_UPDATED'
            ),
            concat(
                '?sort=updated&direction=desc&',
                activity('Read Table Details').output.firstRow.source_api_params
            ),
            concat(
                '?',
                activity('Read Table Details').output.firstRow.source_api_params
            )
        )
    )
)

